import java.util.Scanner;

public class Main {
    static long computeGCD(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long max_b = sc.nextLong();

        long bestA = 0;
        long bestB = 1;
        double minDifference = 1e12;

        for (long b_value = 1; b_value <= max_b; b_value++) {
            long left = 0, right = 100000;
            long a_candidate = 0;

            while (left <= right) {
                long mid = (left + right) >> 1;
                if (mid * b <= a * b_value) {
                    a_candidate = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            left = 0;
            right = 100000;
            long a2_candidate = 0;
            long b2_candidate = b_value;

            while (left <= right) {
                long mid = (left + right) >> 1;
                if (mid * b < a * b_value) {
                    left = mid + 1;
                } else {
                    a2_candidate = mid;
                    right = mid - 1;
                }
            }

            double diff2 = Math.abs((double) a2_candidate / b2_candidate - (double) a / b);
            double diff1 = Math.abs((double) a_candidate / b_value - (double) a / b);

            if (diff2 + 1e-8 < diff1) {
                a_candidate = a2_candidate;
                b2_candidate = b_value;
                diff1 = diff2;
            }

            long g = computeGCD(a_candidate, b2_candidate);
            if (diff1 < minDifference) {
                bestA = a_candidate / g;
                bestB = b2_candidate / g;
                minDifference = diff1;
            }
        }

        System.out.println(bestA + "/" + bestB);
        sc.close();
    }
}
